import{c as a,M as r,h as i,k as o}from"./chunks/framework.MukIDqOt.js";const h=JSON.parse('{"title":"Bibliotecas de Renderização","description":"Bibliotecas e motores gráficos para renderização em tempo real, ray tracing e pesquisa.","frontmatter":{"title":"Bibliotecas de Renderização","sidebar_label":"Bibliotecas","description":"Bibliotecas e motores gráficos para renderização em tempo real, ray tracing e pesquisa."},"headers":[],"relativePath":"bibliotecas.md","filePath":"bibliotecas.md","lastUpdated":1780582189000}'),t={name:"bibliotecas.md"};function n(l,e,s,c,p,d){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="🎨-awesome-render-libraries" tabindex="-1">🎨 Awesome Render Libraries <a class="header-anchor" href="#🎨-awesome-render-libraries" aria-label="Permalink to “🎨 Awesome Render Libraries”">​</a></h1><h2 id="legenda" tabindex="-1">Legenda <a class="header-anchor" href="#legenda" aria-label="Permalink to “Legenda”">​</a></h2><ul><li>🐐 GOAT — Essencial para aprender Computação Gráfica</li><li>⭐ Excelente</li><li>💎 Open Source</li><li>🔥 Muito utilizada na indústria</li><li>🧪 Pesquisa Acadêmica</li><li>⚡ Tempo Real</li></ul><hr><h1 id="rasterizacao-em-tempo-real" tabindex="-1">Rasterização em Tempo Real <a class="header-anchor" href="#rasterizacao-em-tempo-real" aria-label="Permalink to “Rasterização em Tempo Real”">​</a></h1><p>Bibliotecas focadas em desenhar milhões de triângulos rapidamente utilizando a GPU.</p><ul><li><p>🐐 💎 🔥 ⚡ <a href="https://github.com/bkaradzic/bgfx" target="_blank" rel="noreferrer">bgfx</a> - Abstração multiplataforma sobre Vulkan, DirectX, Metal e OpenGL. Excelente para estudar engines e renderizadores modernos sem ficar preso a uma API específica.</p></li><li><p>🐐 💎 ⭐ ⚡ <a href="https://www.ogre3d.org/" target="_blank" rel="noreferrer">OGRE</a> - Engine de renderização orientada a cenas. Ótima para aprender iluminação, materiais, câmeras e gerenciamento de objetos 3D.</p></li><li><p>💎 ⭐ ⚡ <a href="https://irrlicht.sourceforge.io/" target="_blank" rel="noreferrer">Irrlicht</a> - Biblioteca clássica para aprendizado de gráficos 3D. Possui arquitetura simples e fácil de explorar.</p></li><li><p>💎 ⭐ ⚡ <a href="https://urho3d.io/" target="_blank" rel="noreferrer">Urho3D</a> - Renderização em tempo real com física, cenas e animações integradas.</p></li><li><p>💎 ⭐ ⚡ <a href="https://github.com/DiligentGraphics/DiligentEngine" target="_blank" rel="noreferrer">Diligent Engine</a> - Camada moderna que unifica diversas APIs gráficas.</p></li><li><p>⭐ ⚡ <a href="https://github.com/NVIDIAGameWorks/Falcor" target="_blank" rel="noreferrer">Falcor</a> - Framework da NVIDIA usado para pesquisa e prototipação de renderização avançada.</p></li></ul><hr><h1 id="path-tracing-e-ray-tracing" tabindex="-1">Path Tracing e Ray Tracing <a class="header-anchor" href="#path-tracing-e-ray-tracing" aria-label="Permalink to “Path Tracing e Ray Tracing”">​</a></h1><p>Bibliotecas focadas em simular o comportamento físico da luz.</p><ul><li><p>🐐 💎 🔥 🧪 <a href="https://www.pbr-book.org/" target="_blank" rel="noreferrer">PBRT</a> - Referência máxima para aprender renderização fisicamente baseada. O código acompanha o famoso livro &quot;Physically Based Rendering&quot;.</p></li><li><p>🐐 💎 ⭐ 🧪 <a href="https://mitsuba-renderer.org/" target="_blank" rel="noreferrer">Mitsuba</a> - Renderizador acadêmico extremamente utilizado em pesquisas sobre luz, materiais e sensores.</p></li><li><p>💎 ⭐ 🧪 <a href="https://luxcorerender.org/" target="_blank" rel="noreferrer">LuxCoreRender</a> - Renderização baseada em física com foco em realismo.</p></li><li><p>💎 ⭐ 🧪 <a href="https://github.com/tunabrain/tungsten" target="_blank" rel="noreferrer">Tungsten</a> - Renderizador educacional focado em ray tracing moderno.</p></li><li><p>💎 ⭐ 🧪 <a href="https://openmoonray.org/" target="_blank" rel="noreferrer">MoonRay</a> - Renderizador utilizado pela DreamWorks em produções cinematográficas.</p></li><li><p>⭐ 🧪 <a href="https://www.intel.com/content/www/us/en/developer/tools/oneapi/embree-render-kernels.html" target="_blank" rel="noreferrer">Embree</a> - Biblioteca da Intel especializada em acelerar interseções de raios.</p></li></ul><hr><h1 id="pesquisa-academica" tabindex="-1">Pesquisa Acadêmica <a class="header-anchor" href="#pesquisa-academica" aria-label="Permalink to “Pesquisa Acadêmica”">​</a></h1><p>Projetos criados para experimentação de algoritmos e publicação científica.</p><ul><li><p>🐐 💎 🧪 <a href="https://wjakob.github.io/nori/" target="_blank" rel="noreferrer">Nori</a> - Renderizador educacional usado em cursos universitários de Computação Gráfica.</p></li><li><p>🐐 💎 🧪 <a href="https://mitsuba-renderer.org/" target="_blank" rel="noreferrer">Mitsuba 3</a> - Plataforma de pesquisa para óptica computacional, diferenciação automática e simulação de luz.</p></li><li><p>💎 🧪 <a href="https://github.com/taichi-dev/taichi" target="_blank" rel="noreferrer">Taichi Graphics</a> - Framework para experimentação de algoritmos gráficos e físicos.</p></li><li><p>💎 🧪 <a href="https://github.com/mitsuba-renderer/drjit" target="_blank" rel="noreferrer">Dr.Jit</a> - Computação vetorizada e diferenciação automática para renderização.</p></li><li><p>💎 🧪 <a href="https://github.com/ssloy/tinyrenderer" target="_blank" rel="noreferrer">TinyRenderer</a> - Implementação minimalista de um pipeline gráfico completo para estudo.</p></li></ul><hr><h1 id="renderizacao-educacional" tabindex="-1">Renderização Educacional <a class="header-anchor" href="#renderizacao-educacional" aria-label="Permalink to “Renderização Educacional”">​</a></h1><p>Projetos focados em ensinar como um renderizador funciona internamente.</p><ul><li><p>🐐 💎 ⭐ <a href="https://raytracing.github.io/" target="_blank" rel="noreferrer">Ray Tracing in One Weekend</a> - Série de livros que ensina a construir um ray tracer do zero.</p></li><li><p>🐐 💎 ⭐ <a href="https://github.com/ssloy/tinyrenderer" target="_blank" rel="noreferrer">TinyRenderer</a> - Pipeline gráfico implementado em poucas linhas de código.</p></li><li><p>🐐 💎 ⭐ <a href="https://www.scratchapixel.com/" target="_blank" rel="noreferrer">Scratchapixel</a> - Tutoriais extremamente detalhados sobre matemática e algoritmos gráficos.</p></li><li><p>💎 ⭐ <a href="https://github.com/microsoft/DirectX-Graphics-Samples/tree/master/MiniEngine" target="_blank" rel="noreferrer">MiniEngine</a> - Engine educacional da Microsoft.</p></li><li><p>💎 ⭐ <a href="https://github.com/TheCherno/Hazel" target="_blank" rel="noreferrer">TheChernoHazel</a> - Engine criada em série educacional ensinando arquitetura de motores gráficos.</p></li></ul><hr><h1 id="computacao-grafica-cientifica" tabindex="-1">Computação Gráfica Científica <a class="header-anchor" href="#computacao-grafica-cientifica" aria-label="Permalink to “Computação Gráfica Científica”">​</a></h1><p>Bibliotecas usadas para visualização científica e grandes conjuntos de dados.</p><ul><li><p>🐐 💎 ⭐ <a href="https://vtk.org/" target="_blank" rel="noreferrer">VTK</a> - Visualização científica, medicina, engenharia e pesquisa.</p></li><li><p>💎 ⭐ <a href="https://www.paraview.org/" target="_blank" rel="noreferrer">ParaView</a> - Construído sobre o VTK para análise de grandes simulações.</p></li><li><p>💎 ⭐ <a href="https://www.openscenegraph.com/" target="_blank" rel="noreferrer">OpenSceneGraph</a> - Visualização de cenas complexas em aplicações científicas.</p></li></ul><hr><h1 id="frameworks-para-construir-engines" tabindex="-1">Frameworks para Construir Engines <a class="header-anchor" href="#frameworks-para-construir-engines" aria-label="Permalink to “Frameworks para Construir Engines”">​</a></h1><p>Ferramentas que servem como base para criar seu próprio motor gráfico.</p><ul><li><p>🐐 💎 🔥 <a href="https://github.com/bkaradzic/bgfx" target="_blank" rel="noreferrer">bgfx</a> - Uma das melhores bases para criar engines multiplataforma.</p></li><li><p>🐐 💎 ⭐ <a href="https://magnum.graphics/" target="_blank" rel="noreferrer">Magnum</a> - Framework moderno com arquitetura limpa e excelente documentação.</p></li><li><p>💎 ⭐ <a href="https://github.com/DiligentGraphics/DiligentEngine" target="_blank" rel="noreferrer">Diligent Engine</a> - Abstração de APIs modernas.</p></li><li><p>💎 ⭐ <a href="https://www.ogre3d.org/" target="_blank" rel="noreferrer">OGRE</a> - Base sólida para sistemas gráficos orientados a cena.</p></li><li><p>💎 ⭐ <a href="https://urho3d.io/" target="_blank" rel="noreferrer">Urho3D</a> - Estrutura completa para jogos e simulações.</p></li></ul><hr><h1 id="goats-para-aprender-computacao-grafica" tabindex="-1">GOATs para Aprender Computação Gráfica <a class="header-anchor" href="#goats-para-aprender-computacao-grafica" aria-label="Permalink to “GOATs para Aprender Computação Gráfica”">​</a></h1><ul><li>🐐 PBRT — O livro e renderizador mais importante da área.</li><li>🐐 Mitsuba — Pesquisa moderna em iluminação.</li><li>🐐 bgfx — Excelente para criar renderizadores reais.</li><li>🐐 OGRE — Aprendizado de cenas e engines.</li><li>🐐 Ray Tracing in One Weekend — Melhor introdução ao ray tracing.</li><li>🐐 Scratchapixel — Melhor site para entender os algoritmos.</li><li>🐐 TinyRenderer — Entender o pipeline gráfico inteiro.</li><li>🐐 Embree — Aprender aceleração de ray tracing.</li><li>🐐 Magnum — Framework moderno para engines.</li><li>🐐 VTK — Visualização científica profissional.</li></ul><hr>',31)])])}const u=a(t,[["render",n]]);export{h as __pageData,u as default};
